const validBoards=new Set(Object.keys(boardLabels));
function cleanText(v,m=1000){return String(v||'').replace(/<[^>]*>/g,'').replace(/[\u0000-\u001f\u007f]/g,' ').replace(/\s+/g,' ').trim().slice(0,m)}
function normalizeBoard(v='main'){const b=cleanText(v,80).toLowerCase().replace(/[^a-z0-9-]/g,'-');return validBoards.has(b)?b:'main'}
function inferBoardFromPost(p={}){return normalizeBoard(p.board||p.category||'main')}
function json(d,status=200){return new Response(JSON.stringify(d,null,2),{status,headers:jsonHeaders})}
function makeId(){return `signal-${Date.now()}-${Math.random().toString(36).slice(2,10)}`}
function subscriberId(email){let n=0;for(const ch of String(email||''))n=(n*31+ch.charCodeAt(0))>>>0;return 'subscriber-'+n.toString(36)}
async function readBody(request){const type=request.headers.get('content-type')||'';if(type.includes('application/json'))return request.json().catch(()=>({}));const form=await request.formData().catch(()=>null);return form?Object.fromEntries(form.entries()):{}}
function safePost(p={}){const board=normalizeBoard(p.board||inferBoardFromPost(p));return{id:cleanText(p.id||makeId(),120),board,title:cleanText(p.title||'Untitled Signal',140),body:cleanText(p.body||p.message||'',1800),category:cleanText(p.category||'Signal',80),name:cleanText(p.name||'Anonymous',80),sourceUrl:cleanText(p.sourceUrl||p.source||'',500),createdAt:cleanText(p.createdAt||new Date().toISOString(),80),approvedAt:cleanText(p.approvedAt||p.createdAt||new Date().toISOString(),80),status:cleanText(p.status||'live',40)}}
function sortPosts(posts=[]){return posts.slice().sort((a,b)=>String(b.createdAt||'').localeCompare(String(a.createdAt||'')))}
function mergePosts(a=[],b=[]){const map=new Map();for(const p of [...a,...b].map(safePost)){if(p.id)map.set(p.id,p)}return sortPosts([...map.values()])}
function boardCounts(posts=[]){return posts.reduce((a,p)=>{const b=normalizeBoard(p.board);a[b]=(a[b]||0)+1;return a},{main:0,speculation:0,'epstein-alive':0})}
function isSyntheticForumPost(post){const blob=[post&&post.id,post&&post.title,post&&post.body,post&&post.category,post&&post.name,post&&post.status].map(v=>String(v||'').toLowerCase()).join(' ');return /synthetic|smoke test|health check|demo post|fixture|qa post|seed post|system check|generated check|pressure test/.test(blob)}
function publicForumPosts(posts=[]){return sortPosts((posts||[]).map(safePost).filter(p=>p.status==='live'&&!isSyntheticForumPost(p)))}
function filterPostsByBoard(posts=[],board='main'){const b=normalizeBoard(board);return posts.filter(p=>normalizeBoard(p.board)===b)}
async function withTimeout(promise,ms,fallback){let timer;try{return await Promise.race([promise,new Promise(resolve=>{timer=setTimeout(()=>resolve(fallback),ms)})])}finally{clearTimeout(timer)}}
async function getFastForumIndex(env){if(!env.FORUM_POSTS)return[];const raw=await withTimeout(env.FORUM_POSTS.get('posts:index'),700,'[]');try{const arr=JSON.parse(raw||'[]');return Array.isArray(arr)?arr.map(safePost):[]}catch{return[]}}
async function saveFastForumIndex(env,posts=[]){if(!env.FORUM_POSTS)return false;const cleaned=sortPosts(posts.map(safePost)).slice(0,300);return Boolean(await withTimeout(env.FORUM_POSTS.put('posts:index',JSON.stringify(cleaned),{metadata:{updatedAt:new Date().toISOString(),count:cleaned.length,boardCounts:boardCounts(cleaned),storage:'Cloudflare KV FORUM_POSTS'}}).then(()=>true).catch(()=>false),900,false))}
async function forumExport(env,board='all'){const stored=await getFastForumIndex(env);const pub=publicForumPosts(stored);const b=board==='all'?'all':normalizeBoard(board);const posts=b==='all'?pub:filterPostsByBoard(pub,b);return{ok:true,persistent:Boolean(env.FORUM_POSTS),'persistent: true':Boolean(env.FORUM_POSTS),source:env.FORUM_POSTS?'Cloudflare KV FORUM_POSTS':'fast fallback, KV binding unavailable',generatedAt:new Date().toISOString(),board:b,boardLabel:b==='all'?'All Boards':boardLabels[b],boardCounts:boardCounts(pub),count:posts.length,posts:posts.slice(0,100)}}
async function handleForumHealth(env){return json({ok:true,worker:workerName,backend:'src/worker.js',assetBinding:Boolean(env.ASSETS),forumPostsBinding:env.FORUM_POSTS?'connected':'missing',bindingHealthy:Boolean(env.FORUM_POSTS),kvBindingName:'FORUM_POSTS',expectedKvNamespaceTitle:'matrixreprogrammed-forum-posts',expectedKvNamespaceId:'99996d87016d4285a833707cbda5232f',persistence:'Cloudflare KV FORUM_POSTS with posts:index fast path',indexSelfHealing:'deferred',boardAware:true,boardLabels,hardBoardRoutes:Object.keys(hardBoardRouteMap),deployedFrom:'GitHub main',updatedAt})}
