function postsMarkdown(data){return['# Matrix Reprogrammed Signal Board Posts','',`Generated: ${data.generatedAt}`,`Posts: ${data.posts.length}`].concat((data.posts||[]).flatMap(p=>['',`## ${p.title}`,p.body])).join('\n')}
