async function handleSubmitForumPost(request,env,forcedBoard=''){const body=await readBody(request);if(body.website)return json({ok:false,error:'Spam trap triggered'},400);const title=cleanText(body.title||'Reader Signal',140),message=cleanText(body.body||body.message||'Reader submitted a source lead for review.',1800);const board=normalizeBoard(forcedBoard||body.board||'main');const post=safePost({id:makeId(),board,title,body:message,category:body.category||'Signal',name:body.name||'Anonymous',sourceUrl:body.sourceUrl||body.source||'',status:'live'});let saved=false;if(env.FORUM_POSTS){await withTimeout(env.FORUM_POSTS.put(`post:${post.id}`,JSON.stringify(post),{metadata:{createdAt:post.createdAt,title:post.title,status:post.status,board}}).then(()=>true).catch(()=>false),700,false);const posts=mergePosts([post],await getFastForumIndex(env));saved=await saveFastForumIndex(env,posts)}return json({ok:true,persistent:Boolean(env.FORUM_POSTS),saved,storage:env.FORUM_POSTS?'Cloudflare KV FORUM_POSTS':'fast fallback response',indexSelfHealing:'deferred',board,boardLabel:boardLabels[board],post})}
async function handleReportForumPost(request,env,forcedBoard=''){const body=await readBody(request);const board=normalizeBoard(forcedBoard||body.board||'main');const report={id:makeId(),board,postId:cleanText(body.id||body.postId,120),reason:cleanText(body.reason||'Reported by reader',1000),createdAt:new Date().toISOString()};if(env.FORUM_POSTS){await withTimeout(env.FORUM_POSTS.put(`report:${report.id}`,JSON.stringify(report),{metadata:{board,postId:report.postId}}).catch(()=>false),600,false)}return json({ok:true,persistent:Boolean(env.FORUM_POSTS),reportId:report.id,board})}
